mapper.sql:
WHERE ur.user_id = #{query.userId}
AND ur.category = #{query.category}
AND ur.import_source = #{query.importSource}
AND ur.summary_status = #{query.summaryStatus}
AND EXISTS ( SELECT 1 FROM stars_user_repo_tag urt_filter WHERE urt_filter.user_repo_id = ur.id AND urt_filter.tag_id IN
#{tagId}
)
AND ( r.full_name LIKE CONCAT('%', #{query.keyword}, '%') OR r.owner LIKE CONCAT('%', #{query.keyword}, '%') OR r.repo_name LIKE CONCAT('%', #{query.keyword}, '%') OR r.description LIKE CONCAT('%', #{query.keyword}, '%') OR ur.summary_one_liner LIKE CONCAT('%', #{query.keyword}, '%') OR ur.summary_text LIKE CONCAT('%', #{query.keyword}, '%') OR ur.note LIKE CONCAT('%', #{query.keyword}, '%') OR ur.category LIKE CONCAT('%', #{query.keyword}, '%') OR EXISTS ( SELECT 1 FROM stars_user_repo_tag urt_kw INNER JOIN stars_tag t_kw ON urt_kw.tag_id = t_kw.id WHERE urt_kw.user_repo_id = ur.id AND t_kw.user_id = ur.user_id AND t_kw.name LIKE CONCAT('%', #{query.keyword}, '%') ) )
